%%
ATTO_rd=read_betsy_2026('C:\github_trend\raw_data\ATTO_maap_aeth_neph_house',ATTO_st.name); %[output:89d3c672]
%data not ok with clap and psap instead of Ae33 ans maap
%
names_rd=fieldnames(ATTO_rd);
%%
datevec(ATTO_rd.Time(1)) % begin in 2012 %[output:3f0473e4]
datevec(ATTO_rd.Time(end)) % end in 2025 %[output:6dd747f0]
