plotFigControl(ATTO_rd,ATTO_st.name); %[output:6b31ae18] %[output:83074024] %[output:0a715e83] %[output:0b09bf93] %[output:3937db49] %[output:873206d6]
%%
% BP detection for scat coef 

names_sc={'BsB_S', 'BsG_S', 'BsR_S'};
break_ATTO_scat_BP=change_point_analysis_Def(ATTO_rd,names_sc,0.05,'ATTO','scattering'); %[output:7adcd262] %[output:812c256f] %[output:29f30a82] %[output:3577fc85]
T_ATTO_scat_BP=make_table_breakpoints_def(break_ATTO_scat_BP);
%%
% BP detection for abs
names_abs={'BaR_Amaap','Ba3_A'};
break_ATTO_abs_BP=change_point_analysis_Def(ATTO_rd,names_abs,0.05,'ATTO','Absorption'); %[output:40343140] %[output:8e960970] %[output:0d7605c7] %[output:3e56a4fd]
T_ATTO_abs_BP=make_table_breakpoints_def(break_ATTO_abs_BP); %[output:20970411]
%%
lambdaSC=[450;550;700];
lambdaAE=637;
lambdaAE7=[370 470 520 590 660 880 950];
% % lambdaAE7=[370 470 520 590 660 880 950];
ATTO_cal=compute_exp_SSA(ATTO_rd,lambdaSC, lambdaAE7);
names_abs={'Ba1_A', 'Ba2_A', 'Ba3_A', 'Ba4_A', 'Ba5_A', 'Ba6_A', 'Ba7_A'};
