%Questions:
%problems:

%RH: it seems that there is a decrease of Humidity, is there any change in the drying process ?

%scat: there is a lot of long holes: are they real or due to databank problems ?

%%
ATTO_tr=ATTO_rd;
ATTO_tr.y=year(ATTO_tr.Time);
% begin at the beginning of a year: MAAP 2013 - 2025 for MAAP, 2015-2024 for scat and AE, 2
P=timerange('2013-01-01','2026-01-01');
ATTO_tr=ATTO_tr(P,:);

% begin at the beginning of a year:  2014 for scat + abs
Ps=timerange('2013-01-01','2014-01-01');
% end at the beginning of a full year:  2024 for scat + abs
Pe=timerange('2024-01-01','2015-01-01');
names=fieldnames(ATTO_tr);
c=startsWith(names,["Bs";"U"]) | endsWith(names,"_A");
N=names(c) %[output:85967003]
for i=1:length(N)
    ATTO_tr.(N{i})(Ps)=NaN;
    ATTO_tr.(N{i})(Pe)=NaN;
end

